# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TENVİN VE SAKİN NUNUN HÂLLERİ: İDGAM KAVRAMI VE İKİ ÇEŞİDİ</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">1. İDGAM-I MEAL-GUNNE (GUNNELİ İDGAM)</text>\n  <text x="35" y="94" font-size="11.5" font-weight="bold" fill="#1e3a8a">• Harfleri (4 Harf — "يَمْنُو / Yemnu"):</text>\n  <text x="180" y="120" text-anchor="middle" font-size="16" font-weight="bold" fill="#1d4ed8">ي — ن — م — و</text>\n  <text x="35" y="146" font-size="10.5" fill="#1e3a8a">• Kural: Tenvin veya sakin nundan (نْ) sonra bu 4 harften</text>\n  <text x="43" y="162" font-size="10.5" fill="#1e3a8a">biri gelirse nun sesi sonraki harfe katılır ve genizden</text>\n  <text x="43" y="178" font-size="10.5" font-weight="bold" fill="#1d4ed8">gunne sesiyle (1,5 elif miktarı tutularak) okunur.</text>\n  <text x="35" y="202" font-size="11" font-weight="bold" fill="#15803d">• Örnekler: مَنْ يَعْمَلْ · مِنْ نِعْمَةٍ · عَذَابٌ مُقِيمٌ · مِنْ وَالٍ</text>\n  <text x="35" y="224" font-size="10" font-weight="bold" fill="#b91c1c">İstisna (Tek Kelime): دُنْيَا، بُنْيَانٌ، صِنْوَانٌ، قِنْوَانٌ (İzhar!)</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. İDGAM-I BİLA-GUNNE (GUNNESİZ İDGAM)</text>\n  <text x="375" y="94" font-size="11.5" font-weight="bold" fill="#14532d">• Harfleri (2 Harf — Lam ve Ra):</text>\n  <text x="520" y="120" text-anchor="middle" font-size="16" font-weight="bold" fill="#15803d">ل — ر</text>\n  <text x="375" y="146" font-size="10.5" fill="#14532d">• Kural: Tenvin veya sakin nundan (نْ) sonra ل veya ر</text>\n  <text x="383" y="162" font-size="10.5" fill="#14532d">harfi gelirse nun sesi tamamen bu harflere katılır ve</text>\n  <text x="383" y="178" font-size="10.5" font-weight="bold" fill="#166534">GUNNE YAPILMADAN (tutulmadan) şeddeli gibi okunur.</text>\n  <text x="375" y="202" font-size="11" font-weight="bold" fill="#1e40af">• Örnekler: مِنْ لَدُنْهُ (মিল্-ledünhü) · هُدًى لِلْمُتَّقِينَ</text>\n  <text x="375" y="224" font-size="11" font-weight="bold" fill="#1e40af">• Örnekler: مِنْ رَبِّهِمْ (Mir-rabbihim) · غَفُورٌ رَحِيمٌ</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İKLÂB (الْإِقْلَابُ) KURALI, TEK HARFİ (ب) VE UYGULANIŞI</text>\n  <rect x="25" y="45" width="310" height="195" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b45309">İKLÂB TANIMI VE TEK HARFİ</text>\n  <text x="42" y="96" font-size="11" font-weight="bold" fill="#78350f">• Sözlük Anlamı: Bir şeyi bulunduğu hâlden başka</text>\n  <text x="50" y="112" font-size="11" font-weight="bold" fill="#78350f">bir hâle çevirmek, dönüştürmek demektir.</text>\n  <text x="42" y="138" font-size="11.5" font-weight="bold" fill="#b91c1c">• İklâb Harfi (Yalnızca 1 Harf): ب (Bâ)</text>\n  <text x="42" y="164" font-size="10.5" fill="#92400e">• Tecvit Kuralı: Tenvin veya sakin nundan (نْ) hemen</text>\n  <text x="50" y="180" font-size="10.5" fill="#92400e">sonra ب harfi geldiğinde, sakin nun veya tenvin sesi</text>\n  <text x="50" y="196" font-size="10.5" font-weight="bold" fill="#78350f">hâlis bir MİM (م) sesine çevrilir ve dudaklar hafif</text>\n  <text x="50" y="212" font-size="10.5" font-weight="bold" fill="#78350f">temas ettirilerek gunneli biçimde (1,5 elif) tutulur.</text>\n  <rect x="355" y="45" width="320" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="515" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">KUR\'AN\'DA İKLÂB ÖRNEKLERİ VE İŞARETİ</text>\n  <text x="372" y="96" font-size="12" font-weight="bold" fill="#581c87">1. مِنْ بَعْدِ → Okunuşu: مِمْ بَعْدِ (Mim-ba\'di)</text>\n  <text x="372" y="122" font-size="12" font-weight="bold" fill="#581c87">2. أَنْبِئْهُمْ → Okunuşu: أَمْبِئْهُمْ (Embi\'hüm)</text>\n  <text x="372" y="148" font-size="12" font-weight="bold" fill="#581c87">3. سَمِيعٌ بَصِيرٌ → Okunuşu: سَمِيعُمْ بَصِيرٌ</text>\n  <text x="372" y="174" font-size="12" font-weight="bold" fill="#581c87">4. عَلِيمٌ بِذَاتِ الصُّدُورِ → عَلِيمُمْ بِذَاتِ</text>\n  <text x="372" y="204" font-size="10.5" font-weight="bold" fill="#15803d">Mushaf İşareti: Mushaflarda iklâb olan yerlerde sakin nun</text>\n  <text x="372" y="220" font-size="10.5" font-weight="bold" fill="#15803d">veya tenvinin üzerine küçük bir mim (مـ) harfi konulur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TENVİN VE SAKİN NUNUN DÖRT HÂLİ (28 HARFİN BÜTÜNCÜL TABLOSU)</text>\n  <rect x="20" y="45" width="155" height="195" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="97" y="66" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">1. İZHAR (6 Harf)</text>\n  <text x="97" y="92" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">ء هـ ع ح غ خ</text>\n  <text x="30" y="118" font-size="10" fill="#1e3a8a">• Boğaz harfleridir.</text>\n  <text x="30" y="138" font-size="10" fill="#1e3a8a">• Açık ve net okunur.</text>\n  <text x="30" y="158" font-size="10" fill="#1e3a8a">• Gunne (tutma) yapılmaz.</text>\n  <text x="30" y="182" font-size="10" font-weight="bold" fill="#1e40af">Örnek: مِنْ خَوْفٍ</text>\n  <text x="30" y="202" font-size="10" font-weight="bold" fill="#1e40af">Örnek: عَذَابٌ أَلِيمٌ</text>\n  <rect x="188" y="45" width="155" height="195" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="265" y="66" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">2. İHFA (15 Harf)</text>\n  <text x="265" y="90" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">ت ث ج د ذ ز س ش</text>\n  <text x="265" y="106" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">ص ض ط ظ ف ق ك</text>\n  <text x="198" y="130" font-size="10" fill="#14532d">• İzhar ile idgam arası</text>\n  <text x="204" y="144" font-size="10" fill="#14532d">gizleyerek okunur.</text>\n  <text x="198" y="162" font-size="10" fill="#14532d">• Gunneli tutulur.</text>\n  <text x="198" y="184" font-size="10" font-weight="bold" fill="#15803d">Örnek: أَنْفُسِهِمْ</text>\n  <text x="198" y="204" font-size="10" font-weight="bold" fill="#15803d">Örnek: مِنْ قَبْلِ</text>\n  <rect x="356" y="45" width="165" height="195" rx="8" fill="#fffbeb" stroke="#d97706" stroke-width="1.8"/>\n  <text x="438" y="66" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#b45309">3. İDGAM (6 Harf: يَرْمَلُون)</text>\n  <text x="366" y="92" font-size="10" font-weight="bold" fill="#78350f">a) Meal-Gunne (4 Harf):</text>\n  <text x="374" y="108" font-size="11" font-weight="bold" fill="#b45309">ي ن م و (Gunneli)</text>\n  <text x="374" y="124" font-size="10" fill="#92400e">Örnek: فَمَنْ يَعْمَلْ</text>\n  <text x="366" y="148" font-size="10" font-weight="bold" fill="#78350f">b) Bila-Gunne (2 Harf):</text>\n  <text x="374" y="164" font-size="11" font-weight="bold" fill="#b45309">ل ر (Gunnesiz)</text>\n  <text x="374" y="180" font-size="10" fill="#92400e">Örnek: غَفُورٌ رَحِيمٌ</text>\n  <text x="366" y="204" font-size="9.5" fill="#b91c1c">Ayrı iki kelimede olur!</text>\n  <rect x="534" y="45" width="146" height="195" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="607" y="66" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#7e22ce">4. İKLÂB (1 Harf)</text>\n  <text x="607" y="96" text-anchor="middle" font-size="15" font-weight="bold" fill="#6b21a8">ب (Bâ)</text>\n  <text x="544" y="122" font-size="10" fill="#581c87">• Nun sesi م (mim)</text>\n  <text x="550" y="136" font-size="10" fill="#581c87">sesine çevrilir.</text>\n  <text x="544" y="156" font-size="10" fill="#581c87">• Gunneli tutulur.</text>\n  <text x="544" y="182" font-size="10" font-weight="bold" fill="#7e22ce">Örnek: مِنْ بَعْدِ</text>\n  <text x="544" y="202" font-size="10" font-weight="bold" fill="#7e22ce">Örnek: سَمِيعٌ بَصِيرٌ</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
